
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbefe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbefe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.480214798643148e-02, -7.378806266467317e-02, -7.233177032605895e-02, -7.024176061284218e-02, -6.724510262848281e-02, -6.295589537525818e-02, -5.684204912410942e-02, -4.823640160705606e-02, -3.664571798342358e-02, -2.348191813017815e-02, -1.770602992178882e-02, -4.382640268128904e-02, -4.929354254780412e-02, -3.731336217477790e-02, -2.162446592508641e-02, -6.523963963051275e-03, -4.507954345652418e-04, -4.397143961239028e-06, -4.552954857756637e-09, -1.802788877779609e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


